-- Audit trail of every scoring rule that fired for an echocardiogram result.

CREATE TABLE echocardiogram_test_result_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    echocardiogram_test_result_grade_id UUID NOT NULL
        REFERENCES echocardiogram_test_result_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('classification', 'severity', 'completeness', 'follow-up', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_echocardiogram_test_result_grade_rule_grade_id
    ON echocardiogram_test_result_grade_rule(echocardiogram_test_result_grade_id);

