    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE echocardiogram_test_result_grade_rule IS
    'Audit trail of every classification / severity / completeness / follow-up rule that fired for this result.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.echocardiogram_test_result_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-CLASS-CRITICAL-01).';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.axis IS
    'Scoring axis the rule belongs to: classification, severity, completeness, follow-up.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.category IS
    'Category or finding the rule relates to.';
COMMENT ON COLUMN echocardiogram_test_result_grade_rule.description IS
    'Human-readable description of why the rule fired.';

